// This file holds global configuration for the frontend

// Define the base URL for the backend API
window.API_BASE_URL = 'https://wargmirror.onrender.com';

if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
  window.API_BASE_URL = 'http://localhost:3000';
}

/**
 * WARG Platform — Shared API Client
 * ==================================
 * Provides typed helpers for every backend endpoint and a normaliser
 * that maps API response shapes to the GameCard-compatible format.
 *
 * Usage (plain-script — no import needed, loaded before page scripts):
 *   const args = await api.getArgs();
 *   const user = await api.getCurrentUser(); // null for guests
 */

// Auto-detect local development environment
if (!window.API_BASE_URL) {
  if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
    window.API_BASE_URL = 'http://localhost:3000';
  } else {
    window.API_BASE_URL = 'https://wargmirror.onrender.com';
  }
}
var API_BASE = window.API_BASE_URL;

// eslint-disable-next-line no-unused-vars
var api = (function () {

  /* ── Generic fetch wrapper ──────────────────────────────── */
  async function _get(path) {
    const res = await fetch(API_BASE + path, { credentials: 'include' });
    if (!res.ok) {
      throw Object.assign(new Error('API error'), { status: res.status, path });
    }
    return res.json();
  }

  async function _post(path, body) {
    const res = await fetch(API_BASE + path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      credentials: 'include'
    });
    if (!res.ok) {
      throw Object.assign(new Error('API error'), { status: res.status, path });
    }
    return res.json();
  }

  async function _delete(path) {
    const res = await fetch(API_BASE + path, {
      method: 'DELETE',
      credentials: 'include'
    });
    if (!res.ok) {
      throw Object.assign(new Error('API error'), { status: res.status, path });
    }
    return res.json();
  }

  /* ── Data normaliser ────────────────────────────────────── */
  /**
   * Maps an API Arg object → GameCard-compatible shape.
   *
   * API shape:
   *   { arg_id, title, mode, caption, cover_image, like_count, dislike_count,
   *     rating_sum, rating_count, status, play_count, created_at, updated_at,
   *     Creator: { username, avatar } }
   *
   * GameCard shape:
   *   { id, title, mode, caption, emoji, image, progress, progressLabel,
   *     author: { name, initials }, likes, dislikes, rating, featured }
   */
  function normaliseArg(arg) {
    var creator  = arg.Creator || {};
    var username = creator.username || 'Unknown';

    // Build initials from username (up to 2 chars)
    var initials = username
      .split(/[\s_-]+/)
      .slice(0, 2)
      .map(function (w) { return w[0] || ''; })
      .join('')
      .toUpperCase() || '??';

    // Compute rating (0 if never rated)
    var ratingCount = arg.rating_count || 0;
    var rating = ratingCount > 0
      ? Math.round((arg.rating_sum / ratingCount) * 10) / 10
      : 0;

    // cover_image from the DB is a BLOB — the API sends it as a Buffer/null.
    // Until the server serialises it as a data-URL we default to null (emoji fallback).
    var image = null;

    return {
      id:            String(arg.arg_id),
      title:         arg.title        || 'Untitled',
      mode:          arg.mode         || 'solo',
      caption:       arg.caption      || '',
      emoji:         '🎮',
      image:         image,
      progress:      null,
      progressLabel: null,
      author: {
        name:     username,
        initials: initials,
      },
      likes:    arg.like_count    || 0,
      dislikes: arg.dislike_count || 0,
      userVote: arg.user_vote     || null,
      rating:   rating,
      featured: false,
      // Keep raw fields for pages that need them
      _raw: arg,
    };
  }

  /* ── Endpoints ──────────────────────────────────────────── */

  /**
   * Returns the currently authenticated user, or null for guests.
   * Never throws — a 401 is silently swallowed.
   */
  async function getCurrentUser() {
    try {
      return await _get('/auth/me');
    } catch (err) {
      if (err.status === 401) return null;
      throw err;
    }
  }

  /**
   * Returns all published ARGs normalised for GameCard.
   * Public endpoint — works for guests.
   */
  async function getArgs() {
    const args = await _get('/api/args');
    return args.map(normaliseArg);
  }

  /**
   * Returns a single ARG (with Waypoints) normalised for GameCard.
   */
  async function getArgById(id) {
    const arg = await _get('/api/args/' + id);
    return normaliseArg(arg);
  }

  /**
   * Returns a user's public profile.
   * Requires authentication (caller must check for 401).
   */
  async function getUserProfile(userId) {
    return _get('/api/users/' + userId);
  }

  /**
   * Returns all ARGs created by a user (any status), normalised.
   * Requires authentication.
   */
  async function getUserLibrary(userId) {
    const args = await _get('/api/users/' + userId + '/library');
    return args.map(normaliseArg);
  }

  /**
   * Returns active game sessions for a user.
   * Requires authentication.
   */
  async function getActiveSessions(userId) {
    return _get('/api/sessions/' + userId);
  }

  /**
   * Returns friends of a user.
   * Requires authentication.
   */
  async function getFriends(userId) {
    return _get('/api/users/' + userId + '/friends');
  }

  /* ── Game Actions ───────────────────────────────────────── */
  async function voteArg(argId, voteType, userId = 1) { // Defaulting user_id to 1 until auth is hooked up
    return _post('/api/args/' + argId + '/vote', { vote: voteType, user_id: userId });
  }

  async function flagArg(argId, reason, description, reporterId = 1) { // Defaulting user_id to 1 until auth is hooked up
    return _post('/api/args/' + argId + '/flag', { reason, description, reporter_id: reporterId });
  }

  async function removeRecentArg(argId, userId = 1) { // Defaulting user_id to 1 until auth is hooked up
    return _delete('/api/sessions/' + userId + '/arg/' + argId);
  }

  async function submitFeedback(feedbackData) {
    return _post('/api/feedback', feedbackData);
  }

  /* ── Public API ─────────────────────────────────────────── */
  return {
    getCurrentUser,
    getArgs,
    getArgById,
    getUserProfile,
    getUserLibrary,
    getActiveSessions,
    getFriends,
    normaliseArg,
    voteArg,
    flagArg,
    removeRecentArg,
    submitFeedback,
  };

}());

/**
 * WARG Platform — Home Page Script
 * Handles: sidebar/right-panel toggle (desktop collapse + mobile drawer),
 * overlay backdrop, search interactions, friends filtering, notifications.
 */

/* ── Elements ── */
const appShell        = document.getElementById('app-shell');
const sidebar         = document.getElementById('sidebar');
const rightPanel      = document.getElementById('right-panel');
const overlay         = document.getElementById('drawer-overlay');

const btnSidebarToggle    = document.getElementById('btn-sidebar-toggle');
const btnSidebarClose     = document.getElementById('btn-sidebar-close');
const btnRightPanelToggle = document.getElementById('btn-right-panel-toggle');
const btnRightPanelClose  = document.getElementById('btn-right-panel-close');

/* ── Breakpoint: is this a mobile/tablet viewport? ── */
const isMobile = () => window.matchMedia('(max-width: 1023px)').matches;

/* ── Overlay helpers ── */
function showOverlay() {
  overlay.classList.add('is-visible');
  overlay.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden'; // prevent body scroll while drawer open
}

function hideOverlay() {
  overlay.classList.remove('is-visible');
  overlay.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
}

/* ── Left Sidebar ── */
function openSidebar() {
  if (isMobile()) {
    sidebar.classList.add('drawer-open');
    showOverlay();
    btnSidebarToggle.setAttribute('aria-expanded', 'true');
  } else {
    appShell.classList.remove('sidebar-collapsed');
    btnSidebarToggle.setAttribute('aria-expanded', 'true');
  }
}

function closeSidebar() {
  if (isMobile()) {
    sidebar.classList.remove('drawer-open');
    if (!rightPanel || !rightPanel.classList.contains('drawer-open')) hideOverlay();
    btnSidebarToggle.setAttribute('aria-expanded', 'false');
  } else {
    appShell.classList.add('sidebar-collapsed');
    btnSidebarToggle.setAttribute('aria-expanded', 'false');
  }
}

function toggleSidebar() {
  if (isMobile()) {
    sidebar.classList.contains('drawer-open') ? closeSidebar() : openSidebar();
  } else {
    appShell.classList.contains('sidebar-collapsed') ? openSidebar() : closeSidebar();
  }
}

/* ── Right Panel ── */
function openRightPanel() {
  if (isMobile()) {
    rightPanel.classList.add('drawer-open');
    showOverlay();
    btnRightPanelToggle.setAttribute('aria-expanded', 'true');
  } else {
    appShell.classList.remove('right-collapsed');
    btnRightPanelToggle.setAttribute('aria-expanded', 'true');
  }
}

function closeRightPanel() {
  if (isMobile()) {
    rightPanel.classList.remove('drawer-open');
    if (!sidebar.classList.contains('drawer-open')) hideOverlay();
    btnRightPanelToggle.setAttribute('aria-expanded', 'false');
  } else {
    appShell.classList.add('right-collapsed');
    btnRightPanelToggle.setAttribute('aria-expanded', 'false');
  }
}

function toggleRightPanel() {
  if (isMobile()) {
    rightPanel.classList.contains('drawer-open') ? closeRightPanel() : openRightPanel();
  } else {
    appShell.classList.contains('right-collapsed') ? openRightPanel() : closeRightPanel();
  }
}

/* ── Wire up buttons ── */
btnSidebarToggle?.addEventListener('click', toggleSidebar);
btnSidebarClose?.addEventListener('click', closeSidebar);
btnRightPanelToggle?.addEventListener('click', toggleRightPanel);
btnRightPanelClose?.addEventListener('click', closeRightPanel);

/* Dismiss drawers when tapping overlay */
overlay?.addEventListener('click', () => {
  closeSidebar();
  closeRightPanel();
});

/* Dismiss with Escape key */
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    closeSidebar();
    closeRightPanel();
  }
});

/* ── Adapt state on viewport resize ── */
// When going from mobile → desktop, clean up drawer classes
window.addEventListener('resize', () => {
  if (!isMobile()) {
    if (sidebar) sidebar.classList.remove('drawer-open');
    if (rightPanel) rightPanel.classList.remove('drawer-open');
    if (overlay) hideOverlay();
  }
});

/* ── Navigation: active state ── */
const navItems = document.querySelectorAll('.nav-item');

navItems.forEach(item => {
  item.addEventListener('click', () => {
    // Close sidebar drawer after nav on mobile
    if (isMobile()) closeSidebar();

    navItems.forEach(n => {
      n.classList.remove('active');
      n.removeAttribute('aria-current');
    });
    item.classList.add('active');
    item.setAttribute('aria-current', 'page');
  });
});

/* ── Search: focus expansion ── */
const searchInput = document.getElementById('search-input');

searchInput?.addEventListener('focus', () => {
  searchInput.closest('.topbar__search')?.style.setProperty('max-inline-size', '560px');
});
searchInput?.addEventListener('blur', () => {
  searchInput.closest('.topbar__search')?.style.removeProperty('max-inline-size');
});

/* '/' shortcut to focus search */
document.addEventListener('keydown', e => {
  const tag = document.activeElement.tagName.toLowerCase();
  if (e.key === '/' && tag !== 'input' && tag !== 'textarea') {
    e.preventDefault();
    searchInput?.focus();
  }
});

/* ── Friends search: live filter ── */
const friendsSearchInput = document.getElementById('friends-search-input');

friendsSearchInput?.addEventListener('input', () => {
  const query = friendsSearchInput.value.toLowerCase().trim();
  const friendItems = document.querySelectorAll('.friend-item');
  friendItems.forEach(item => {
    const name = item.querySelector('.friend-item__name')?.textContent.toLowerCase() ?? '';
    item.closest('li').style.display = (!query || name.includes(query)) ? '' : 'none';
  });
});

/* ── Notification badge clear ── */
const notifBtn = document.getElementById('btn-notifications');
notifBtn?.addEventListener('click', () => {
  if (notifBtn.dataset.count) {
    notifBtn.removeAttribute('data-count');
    notifBtn.setAttribute('aria-label', 'Notifications');
  }
});

/* ── Initialize Data from API ── */



function showRowEmpty(rowId, message) {
  var container = document.getElementById(rowId);
  if (!container) return;
  container.innerHTML = '<p class="row-empty-msg">' + (message || 'No games found.') + '</p>';
}

async function initHomeData() {
  // If we are not on the home page, exit early to prevent container null errors
  if (!document.getElementById('row-recent')) return;

  if (typeof api === 'undefined') {
    console.error('API not loaded'); return;
  }

  // Show skeletons immediately
  GameCard.renderSkeletons('row-recent', 4);
  GameCard.renderSkeletons('row-new', 4);
  GameCard.renderSkeletons('row-creators', 4);

  // Fetch ARGs (public) and current user (optional) in parallel
  var results = await Promise.allSettled([
    api.getArgs(),
    api.getCurrentUser()
  ]);

  var args = results[0].status === 'fulfilled' ? results[0].value : [];
  var currentUser = results[1].status === 'fulfilled' ? results[1].value : null;

  // ── Update topbar avatar & user-gated UI ──
  if (currentUser) {
    var avatarBtn = document.getElementById('btn-profile');
    if (avatarBtn) {
      var img = avatarBtn.querySelector('img');
      if (img) {
        img.src = 'https://api.dicebear.com/9.x/identicon/svg?seed=' +
          encodeURIComponent(currentUser.username) + '&backgroundColor=1a1816';
        img.alt = currentUser.username + ' avatar';
      }
    }

    // Fetch user profile for stats
    try {
      var profile = await api.getUserProfile(currentUser.user_id);
      var statPoints = document.querySelector('.stat-block__value--green');
      if (statPoints) statPoints.textContent = (profile.total_points || 0).toLocaleString();
      var statDist = document.querySelector('[data-stat="distance"]');
      if (statDist) statDist.textContent = Math.round((profile.distance_walked_m || 0) / 1000) + ' km';
    } catch { /* profile stats are non-critical */ }

    // Fetch and render friends
    try {
      var friends = await api.getFriends(currentUser.user_id);
      renderFriends(friends);
    } catch (err) {
      console.error('Failed to fetch friends', err);
    }

    // Fetch active sessions for "Recently Played"
    var sessionArgIds = new Set();
    try {
      var sessions = await api.getActiveSessions(currentUser.user_id);
      sessions.forEach(function (s) {
        if (s.Arg && s.Arg.arg_id) sessionArgIds.add(String(s.Arg.arg_id));
      });
    } catch { /* fallback handled below */ }

    // Recently Played = ARGs with an active session, no fallback
    var recentArgs = sessionArgIds.size > 0
      ? args.filter(function (a) { return sessionArgIds.has(a.id); })
      : [];

    // Filter out locally dismissed ARGs
    var dismissed = [];
    try { dismissed = JSON.parse(localStorage.getItem('warg_dismissed_recent') || '[]'); } catch { /* ignore */ }
    recentArgs = recentArgs.filter(function (a) { return dismissed.indexOf(a.id) === -1; });

    if (recentArgs.length === 0) {
      showRowEmpty('row-recent', 'No games played yet.');
    } else {
      GameCard.renderRow('row-recent', recentArgs, { showRemove: true });
    }
  } else {
    // Guest: show "My Progress" prompt
    var activityCard = document.querySelector('.activity-card__stats');
    if (activityCard) {
      activityCard.innerHTML =
        '<p style="color:var(--color-text-muted);font-size:var(--font-size-caption);text-align:center;padding:var(--space-3) 0">' +
        '<a href="login.html" style="color:var(--color-accent)">Log in</a> to track your progress and recent games.</p>';
    }

    // Guest: show login prompt for friends list
    var onlineList = document.getElementById('online-friends-list');
    var offlineList = document.getElementById('offline-friends-list');
    if (onlineList) onlineList.innerHTML = '<li style="padding:1rem;color:var(--text-muted);font-size:var(--font-size-sm);text-align:center;">Log in to see friends</li>';
    if (offlineList) offlineList.innerHTML = '';

    // Guest recently played: none
    var newestArgs = [];

    // Filter out locally dismissed ARGs
    var guestDismissed = [];
    try { guestDismissed = JSON.parse(localStorage.getItem('warg_dismissed_recent') || '[]'); } catch { /* ignore */ }
    newestArgs = newestArgs.filter(function (a) { return guestDismissed.indexOf(a.id) === -1; });

    if (newestArgs.length === 0) {
      showRowEmpty('row-recent', 'Log in to track your recent games.');
    } else {
      GameCard.renderRow('row-recent', newestArgs, { showRemove: true });
    }
  }

  // ── New & Trending — sorted by created_at desc ──
  var trendingArgs = args.slice().sort(function (a, b) {
    return new Date(b._raw.created_at) - new Date(a._raw.created_at);
  }).slice(0, 10);
  if (trendingArgs.length === 0) {
    showRowEmpty('row-new', 'No new games yet.');
  } else {
    GameCard.renderRow('row-new', trendingArgs);
  }

  // ── From Creators — sorted by play_count desc ──
  var creatorsArgs = args.slice().sort(function (a, b) {
    return (b._raw.play_count || 0) - (a._raw.play_count || 0);
  }).slice(0, 10);
  if (creatorsArgs.length === 0) {
    showRowEmpty('row-creators', 'No games available yet.');
  } else {
    GameCard.renderRow('row-creators', creatorsArgs);
  }
  // Init horizontal scroll for cards
  initCardScrolls();
}

/* ── Drag-to-scroll for card rows ── */
function initCardScrolls() {
  document.querySelectorAll('.card-row').forEach(row => {
    let isDown = false;
    let startX;
    let scrollLeft;

    row.addEventListener('mousedown', e => {
      isDown = true;
      row.classList.add('is-dragging');
      startX = e.pageX - row.offsetLeft;
      scrollLeft = row.scrollLeft;
    });
    row.addEventListener('mouseleave', () => {
      isDown = false;
      row.classList.remove('is-dragging');
    });
    row.addEventListener('mouseup', () => {
      isDown = false;
      row.classList.remove('is-dragging');
    });
    row.addEventListener('mousemove', e => {
      if (!isDown) return;
      e.preventDefault();
      const x = e.pageX - row.offsetLeft;
      const walk = (x - startX) * 1.5;
      row.scrollLeft = scrollLeft - walk;
    });
  });
}

function renderFriends(friends) {
  const onlineList = document.getElementById('online-friends-list');
  const offlineList = document.getElementById('offline-friends-list');
  const onlineCount = document.getElementById('online-friends-count');
  
  if (!onlineList || !offlineList) return;

  onlineList.innerHTML = '';
  offlineList.innerHTML = '';

  let onlineFriends = 0;

  friends.forEach(friend => {
    const isOnline = friend.GameSessions && friend.GameSessions.length > 0;
    const session = isOnline ? friend.GameSessions[0] : null;
    const gameTitle = session && session.Arg ? session.Arg.title : 'an unknown game';
    
    const activityText = isOnline ? `Playing: ${gameTitle}` : 'Offline';
    const statusClass = isOnline ? 'status--online' : 'status--offline';
    
    const initials = (friend.username || '??').substring(0, 2).toUpperCase();
    
    let avatarImg;
    if (friend.avatar) {
      // Assuming avatar is returned as base64 or buffer. If buffer, we might need different handling. 
      // Dicebear is used natively as fallback.
      avatarImg = `<div class="friend-item__avatar-img" aria-hidden="true">${initials}</div>`;
    } else {
      avatarImg = `<div class="friend-item__avatar-img" aria-hidden="true">${initials}</div>`;
    }

    const li = document.createElement('li');
    li.innerHTML = `
      <div class="friend-item" role="button" tabindex="0" aria-label="${friend.username} is ${activityText}">
        <div class="friend-item__avatar">
          ${avatarImg}
          <span class="friend-item__status-dot ${statusClass}" aria-label="${isOnline ? 'Online' : 'Offline'}"></span>
        </div>
        <div class="friend-item__info">
          <div class="friend-item__name">${friend.username}</div>
          <div class="friend-item__activity">${activityText}</div>
        </div>
        <button class="friend-item__action" aria-label="Invite ${friend.username} to a game">Invite</button>
      </div>
    `;

    if (isOnline) {
      onlineList.appendChild(li);
      onlineFriends++;
    } else {
      offlineList.appendChild(li);
    }
  });

  if (onlineCount) onlineCount.textContent = onlineFriends;

  if (onlineFriends === 0) {
    onlineList.innerHTML = '<li style="padding:1rem;color:var(--text-muted);font-size:var(--font-size-sm);text-align:center;">No friends online</li>';
  }
  if (friends.length - onlineFriends === 0) {
    offlineList.innerHTML = '<li style="padding:1rem;color:var(--text-muted);font-size:var(--font-size-sm);text-align:center;">No offline friends</li>';
  }
}

// Kick off
document.addEventListener('DOMContentLoaded', initHomeData);

/* ── Friend item keyboard activation ── */
document.querySelectorAll('.friend-item[role="button"]').forEach(item => {
  item.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      item.click();
    }
  });
});

/* ── Invite link: clipboard ── */
const inviteBtn = document.getElementById('btn-invite-friends');
inviteBtn?.addEventListener('click', async () => {
  const link = `${location.origin}/invite?ref=player`;
  try {
    await navigator.clipboard.writeText(link);
    const orig = inviteBtn.textContent;
    inviteBtn.textContent = 'Copied!';
    setTimeout(() => { inviteBtn.textContent = orig; }, 2000);
  } catch {
    const orig = inviteBtn.textContent;
    inviteBtn.textContent = 'Copy failed';
    setTimeout(() => { inviteBtn.textContent = orig; }, 2000);
  }
});

/* ── Handle removing from recent ── */
document.addEventListener('warg:removed-recent', function(e) {
  var argId = e.detail.argId;

  // Persist to localStorage so the card stays hidden across reloads
  try {
    var dismissed = JSON.parse(localStorage.getItem('warg_dismissed_recent') || '[]');
    if (dismissed.indexOf(argId) === -1) {
      dismissed.push(argId);
      localStorage.setItem('warg_dismissed_recent', JSON.stringify(dismissed));
    }
  } catch { /* ignore */ }

  var card = document.querySelector('#row-recent .game-card[data-game-id="' + argId + '"]');
  if (card) {
    card.remove();
    var row = document.getElementById('row-recent');
    if (row && row.children.length === 0) {
      showRowEmpty('row-recent', 'No games played yet.');
    }
  }
});

/* ── Feedback Modal ── */
const feedbackModal = document.getElementById('feedback-modal');
const btnFeedback = document.getElementById('btn-feedback');
const btnCloseFeedback = document.getElementById('btn-close-feedback');
const btnCancelFeedback = document.getElementById('btn-cancel-feedback');
const feedbackForm = document.getElementById('feedback-form');

function openFeedbackModal() {
  if (feedbackModal) {
    feedbackModal.classList.add('is-open');
    feedbackModal.setAttribute('aria-hidden', 'false');
  }
}

function closeFeedbackModal() {
  if (feedbackModal) {
    feedbackModal.classList.remove('is-open');
    feedbackModal.setAttribute('aria-hidden', 'true');
    if (feedbackForm) feedbackForm.reset();
  }
}

btnFeedback?.addEventListener('click', openFeedbackModal);
btnCloseFeedback?.addEventListener('click', closeFeedbackModal);
btnCancelFeedback?.addEventListener('click', closeFeedbackModal);

feedbackModal?.addEventListener('click', e => {
  if (e.target === feedbackModal) closeFeedbackModal();
});

function showToast(message) {
  const toast = document.getElementById('toast');
  if (!toast) return;
  toast.textContent = message;
  toast.classList.add('show');
  setTimeout(() => {
    toast.classList.remove('show');
  }, 3000);
}

feedbackForm?.addEventListener('submit', async e => {
  e.preventDefault();
  
  const submitBtn = feedbackForm.querySelector('button[type="submit"]');
  const originalText = submitBtn.textContent;
  submitBtn.disabled = true;
  submitBtn.textContent = 'Submitting...';

  try {
    const formData = new FormData(feedbackForm);
    const data = Object.fromEntries(formData);
    
    await api.submitFeedback(data);
    
    closeFeedbackModal();
    showToast('Thank you for your feedback!');
  } catch (error) {
    console.error('Failed to submit feedback:', error);
    showToast('Failed to submit feedback. Please try again.');
  } finally {
    submitBtn.disabled = false;
    submitBtn.textContent = originalText;
  }
});

/**
 * WARG Platform — Edit / Create WARG Script
 * Uses MapModal for real geographic waypoint placement.
 */

import { MapModal } from './components/MapModal.js';

document.addEventListener('DOMContentLoaded', async () => {
  const API_BASE = window.API_BASE_URL || 'https://wargmirror.onrender.com';
  
  // ── Create vs Edit mode ──
  const isCreateMode = window.location.pathname.includes('create_warg');
  const urlParams = new URLSearchParams(window.location.search);
  let currentArgId = urlParams.get('id');

  let nodes = [];
  let edges = [];
  let nextId = 1;
  let nextEdgeId = 1;

  // UI Elements for Title/Desc
  const titleEl = document.getElementById('arg-title');
  const descEl = document.getElementById('arg-desc');

  const mapBackendGameTypeToFrontend = (gameType) => {
    const map = {
      'gps_proximity': { type: 'gps', label: 'GPS Location' },
      'ar_object_scan': { type: 'ar', label: 'AR Object Scan' },
      'qr_barcode': { type: 'barcode', label: 'Barcode Game' },
      'text_answer': { type: 'text_answer', label: 'QnA / MCQ' }
    };
    return map[gameType] || { type: 'gps', label: 'GPS Location' };
  };

  if (!isCreateMode && currentArgId) {
    try {
      const res = await fetch(`${API_BASE}/api/args/${currentArgId}`, { credentials: 'include' });
      if (res.ok) {
        const argData = await res.json();
        if (titleEl) titleEl.textContent = argData.title;
        if (descEl) descEl.textContent = argData.description || 'Add a description for your WARG…';
        
        // Map Waypoints to nodes
        const idMap = {}; // mapping waypoint_id to frontend node id
        if (argData.Waypoints) {
          argData.Waypoints.forEach(wp => {
            const nodeId = `wp${nextId++}`;
            idMap[wp.waypoint_id] = nodeId;
            
            const nodeGames = [];
            if (wp.Minigames && wp.Minigames.length > 0) {
              wp.Minigames.forEach(mg => {
                const mappedType = mapBackendGameTypeToFrontend(mg.game_type);
                nodeGames.push({
                  type: mappedType.type,
                  gamemode: mappedType.label,
                  minigame_config: mg.config_json || null
                });
              });
            }

            nodes.push({
              id: nodeId,
              waypoint_id: wp.waypoint_id,
              lat: wp.location.coordinates[1],
              lng: wp.location.coordinates[0],
              title: wp.title,
              description: wp.description,
              games: nodeGames
            });
          });
        }

        if (argData.WaypointEdges) {
          argData.WaypointEdges.forEach(edge => {
            let triggers = [];
            let conditions = edge.conditions_json;
            if (typeof conditions === 'string') {
              try { conditions = JSON.parse(conditions); } catch { /* ignore parse error */ }
            }
            if (conditions && Array.isArray(conditions)) {
              const fromWpData = (argData.Waypoints || []).find(w => w.waypoint_id === edge.from_waypoint_id);
              if (fromWpData && fromWpData.Minigames) {
                 triggers = conditions.map(cond => {
                   const index = fromWpData.Minigames.findIndex(mg => mg.game_id === cond.game_id);
                   return { game_index: index, outcome: cond.outcome };
                 }).filter(t => t.game_index !== -1);
              }
            }
            edges.push({
              id: `e${nextEdgeId++}`,
              from: idMap[edge.from_waypoint_id],
              to: idMap[edge.to_waypoint_id],
              triggers
            });
          });
        }
      }
    } catch (err) {
      console.error('Failed to fetch ARG data:', err);
    }
  } else if (!isCreateMode) {
    // Demo data for visual testing if no ID provided in edit mode
    nodes = [
      { id: 'wp1', lat: -26.19233, lng: 28.02987, title: 'The Great Hall', description: 'Find the plaque near the entrance.', games: [{ gamemode: 'GPS Location', type: 'gps' }] },
      { id: 'wp2', lat: -26.19075, lng: 28.03215, title: 'Library Archway', description: 'Scan the historic archway to reveal the hidden message.', games: [{ gamemode: 'AR Object Scan', type: 'ar' }] },
      { id: 'wp3', lat: -26.19320, lng: 28.02790, title: 'Coffee Shop Secret', description: 'Scan the special barcode on the cup.', games: [{ gamemode: 'Barcode Game', type: 'barcode' }] }
    ];
    edges = [
      { id: 'e1', from: 'wp1', to: 'wp2', triggers: [] },
      { id: 'e2', from: 'wp2', to: 'wp3', triggers: [] }
    ];
    nextId = 4;
    nextEdgeId = 3;
  }

  let selectedId = null;
  let selectedType = null; // 'node' or 'edge'
  let isPlacementMode = false;
  let dragState = null; // null | { type: 'edge_draw', from: 'wp1' }

  // ── Elements ──
  const btnAddWaypoint = document.getElementById('btn-add-waypoint');

  // Right Panel Elements
  const panelEmptyState = document.getElementById('panel-empty-state');

  // Node Editor Elements
  const waypointEditor = document.getElementById('waypoint-editor');
  const editorTitle = document.getElementById('editor-title');
  const editorDesc = document.getElementById('editor-desc');
  const btnRemoveWaypoint = document.getElementById('btn-remove-waypoint');

  // Edge Editor Elements
  const edgeEditor = document.getElementById('edge-editor');
  const btnRemoveEdge = document.getElementById('btn-remove-edge');

  // Global Save / Publish
  const btnGlobalSave = document.getElementById('btn-global-save');
  const btnGlobalPublish = document.getElementById('btn-global-publish');

  // Confirm Modal Elements
  const confirmModalOverlay = document.getElementById('confirm-modal-overlay');
  const confirmModalTitle = document.getElementById('confirm-modal-title');
  const confirmModalDesc = document.getElementById('confirm-modal-desc');
  const btnCloseConfirmModal = document.getElementById('btn-close-confirm-modal');
  const btnCancelConfirm = document.getElementById('btn-cancel-confirm');
  const btnAcceptConfirm = document.getElementById('btn-accept-confirm');
  let confirmCallback = null;

  // Alert Modal Elements
  const alertModalOverlay = document.getElementById('alert-modal-overlay');
  const alertModalDesc = document.getElementById('alert-modal-desc');
  const btnCloseAlertModal = document.getElementById('btn-close-alert-modal');
  const btnAcceptAlert = document.getElementById('btn-accept-alert');

  // ── Initialise Leaflet map in editor mode ──
  const mapModal = new MapModal();
  await mapModal.initEditor({
    nodes,
    onMapClick(lat, lng) {
      if (!isPlacementMode) return;
      const newNode = {
        id: `wp${nextId++}`,
        lat, lng,
        title: 'New Waypoint',
        description: '',
        gamemode: 'GPS Location',
        type: 'gps'
      };
      nodes.push(newNode);
      mapModal.addEditorNode(newNode);
      mapModal.updateEditorEdges(edges, nodes);
      selectItem('node', newNode.id);
      isPlacementMode = false;
      _setPlacementCursor(false);
    },
    onNodeSelected(id) {
      selectItem('node', id);
    },
    onEdgeSelected(id) {
      selectItem('edge', id);
    },
    onNodeMoving(id, lat, lng) {
      const node = nodes.find(n => n.id === id);
      if (node) { node.lat = lat; node.lng = lng; }
      mapModal.updateEditorEdges(edges, nodes);
    },
    onNodeMoved(id, lat, lng) {
      const node = nodes.find(n => n.id === id);
      if (node) { node.lat = lat; node.lng = lng; }
      mapModal.updateEditorEdges(edges, nodes);
    },
    onMapDeselect() {
      clearSelection();
    },
    onNodeCoreDown(id) {
      dragState = { type: 'edge_draw', from: id };
      _setPlacementCursor(true);
    },
    onMapMouseMove(lat, lng) {
      if (dragState && dragState.type === 'edge_draw') {
        mapModal.setTempEdge(dragState.from, lat, lng);
      } else if (isPlacementMode) {
        mapModal.updateGhostNode(lat, lng);
      }
    },
    onNodeMouseUp(id) {
      if (dragState && dragState.type === 'edge_draw' && dragState.from !== id) {
        // Prevent duplicate edges
        const exists = edges.some(edge => edge.from === dragState.from && edge.to === id);
        if (!exists) {
          if (hasPath(id, dragState.from)) {
            openAlertModal("Cannot connect waypoints: This would create a cyclic loop. WARGs must be a directed acyclic graph (DAG).");
          } else {
            const newEdge = { id: `e${nextEdgeId++}`, from: dragState.from, to: id, triggers: [] };
            edges.push(newEdge);
            selectItem('edge', newEdge.id);
          }
        }
      }
      _endEdgeDraw();
    },
    onMapMouseUp() {
      if (dragState && dragState.type === 'edge_draw') {
        _endEdgeDraw();
      }
    }
  });

  function hasPath(fromId, toId) {
    if (fromId === toId) return true;
    const visited = new Set();
    const queue = [fromId];
    while (queue.length > 0) {
      const current = queue.shift();
      if (current === toId) return true;
      if (!visited.has(current)) {
        visited.add(current);
        const outgoingEdges = edges.filter(e => e.from === current);
        for (const edge of outgoingEdges) {
          queue.push(edge.to);
        }
      }
    }
    return false;
  }

  function _endEdgeDraw() {
    dragState = null;
    mapModal.clearTempEdge();
    mapModal.updateEditorEdges(edges, nodes);
    _setPlacementCursor(false);
  }

  // Paint initial nodes onto the map
  nodes.forEach(n => mapModal.addEditorNode(n));
  mapModal.updateEditorEdges(edges, nodes);
  clearSelection();

  // ── Placement cursor helper ──
  function _setPlacementCursor(on) {
    const mapEl = document.getElementById('game-map');
    if (mapEl) mapEl.style.cursor = on ? 'crosshair' : '';
    if (!on && mapModal) {
      mapModal.hideGhostNode();
    }
  }

  // ── Panel Management ──
  function selectItem(type, id) {
