        setLoadingState(btnAcceptConfirm, true, origText);
        try {
          await confirmCallback();
        } finally {
          setLoadingState(btnAcceptConfirm, false, origText);
          closeConfirmModal();
        }
      } else {
        closeConfirmModal();
      }
    });
  }

  // ── Alert Modal Logic ──
