  if (btnAcceptAlert) btnAcceptAlert.addEventListener('click', closeAlertModal);

  if (alertModalOverlay) {
    alertModalOverlay.addEventListener('click', (e) => {
      if (e.target === alertModalOverlay) closeAlertModal();
